def predict(board, action):
    if action[0] == 'MOUSE' and action[1] == 4 and action[2] == 37:
        row, col = action[1], action[2]
        old_char = board[row][col]
        new_char = 'W' if old_char == 'G' else 'G'
        board[row][col] = new_char
        for r in range(max(0, row-4), min(64, row+5)):
            for c in range(max(0, col-4), min(64, col+5)):
                if (r, c) != (row, col):
                    if board[r][c] == 'p':
                        board[r][c] = new_char
    return [''.join(row) for row in board]
